mapper.select:
SELECT d.dept_id AS deptId, t.province_id AS provinceId, t.city_id AS cityId, t.county_id AS countyId, t.town_code as townCode, d.industry_code as industryCode FROM vm_organ_device_rel_t d INNER JOIN vm_order_devices o ON o.tenant_id = d.tenant_id and o.industry_code = d.industry_code and o.device_code = d.device_code INNER JOIN vm_device_info_t t ON d.device_code = t.device_code WHERE d.tenant_id = #{tenantId} AND d.device_type = 4 AND t.delete_flag = '0' AND d.industry_code in
#{item}
AND o.ord_status in (0,1,2) GROUP BY d.industry_code, d.dept_id, t.province_id, t.city_id, t.county_id, t.town_code UNION SELECT d.dept_id AS deptId, it.province_id AS provinceId, it.city_id AS cityId, it.county_id AS countyId, it.town_code as townCode, d.industry_code as industryCode FROM vm_organ_device_rel_t d INNER JOIN vm_order_sensor_devices o ON o.tenant_id = d.tenant_id and o.industry_code = d.industry_code and o.device_code = d.device_code LEFT JOIN vm_iot_device_t it ON d.device_code = it.device_code WHERE d.tenant_id = #{tenantId} AND d.device_type in (8, 10) AND it.delete_flag = '0' AND d.industry_code in
#{item}
AND o.ord_status in (0,1,2) GROUP BY d.industry_code, d.dept_id, it.province_id, it.city_id, it.county_id, it.town_code UNION SELECT d.dept_id AS deptId, t.province_code AS provinceId, t.city_code AS cityId, t.county_code AS countyId, t.town_code as townCode, d.industry_code as industryCode FROM vm_organ_device_rel_t d INNER JOIN vm_order_uav_devices o ON o.tenant_id = d.tenant_id and o.industry_code = d.industry_code and o.device_code = d.device_code INNER JOIN vm_uav_device_info_t t ON d.device_code = t.device_code WHERE d.tenant_id = #{tenantId} AND d.device_type = 11 AND t.delete_flag = '0' AND d.industry_code in
#{item}
AND o.ord_status in (0,1,2) GROUP BY d.industry_code, d.dept_id, t.province_code, t.city_code, t.county_code, t.town_code UNION SELECT d.dept_id AS deptId, t.province_code AS provinceId, t.city_code AS cityId, t.county_code AS countyId, t.town_code as townCode, d.industry_code as industryCode FROM vm_organ_device_rel_t d INNER JOIN vm_order_uav_nest_devices o ON o.tenant_id = d.tenant_id and o.industry_code = d.industry_code and o.device_code = d.device_code INNER JOIN vm_uav_nest_device_info t ON d.device_code = t.device_code WHERE d.tenant_id = #{tenantId} AND d.device_type = 15 AND t.delete_flag = '0' AND d.industry_code in
#{item}
AND o.ord_status in (0,1,2) GROUP BY d.industry_code, d.dept_id, t.province_code, t.city_code, t.county_code, t.town_code UNION SELECT d.dept_id AS deptId, it.province_code AS provinceId, it.city_code AS cityId, it.county_code AS countyId, it.town_code as townCode, d.industry_code as industryCode FROM vm_organ_device_rel_t d INNER JOIN vm_order_horn_devices o ON o.tenant_id = d.tenant_id and o.industry_code = d.industry_code and o.device_code = d.device_code LEFT JOIN vm_horn_device_info_t it ON d.device_code = it.device_code WHERE d.tenant_id = #{tenantId} AND d.device_type = 12 AND it.delete_flag = '0' AND d.industry_code in
#{item}
AND o.ord_status in (0,1,2) GROUP BY d.industry_code, d.dept_id, it.province_code, it.city_code, it.county_code, it.town_code UNION SELECT d.dept_id AS deptId, it.province_code AS provinceId, it.city_code AS cityId, it.county_code AS countyId, it.town_code as townCode, d.industry_code as industryCode FROM vm_organ_device_rel_t d INNER JOIN vm_order_recorder_devices o ON o.tenant_id = d.tenant_id and o.industry_code = d.industry_code and o.device_code = d.device_code LEFT JOIN vm_recorder_device_info_t it ON d.device_code = it.device_code WHERE d.tenant_id = #{tenantId} AND d.device_type = 13 AND it.delete_flag = '0' AND d.industry_code in
#{item}
AND o.ord_status in (0,1,2) GROUP BY d.industry_code, d.dept_id, it.province_code, it.city_code, it.county_code, it.town_code UNION SELECT d.dept_id AS deptId, d.province_code AS provinceId, d.city_code AS cityId, d.county_code AS countyId, d.street_code as townCode, d.industry_code as industryCode FROM vm_organ_street_rel_t d INNER JOIN vm_order_services_rel o ON o.tenant_id = d.tenant_id and o.industry_code = d.industry_code and o.county_code = d.county_code WHERE d.tenant_id = #{tenantId} AND d.delete_flag = '0' AND d.category_code = 9 AND d.industry_code in
#{item}
AND o.ord_status in (0,1,2) GROUP BY d.industry_code, d.dept_id, d.province_code, d.city_code, d.county_code, d.street_code

