mapper.select:
select s.tenant_name, d.TENANT_ID as tenantId, d.TENANT_TOWER_DEPT_ID as tenantTowerDeptId, d.id, d.dept_id, d.parent_id,d.parent_name, d.ancestors, d.dept_name, d.order_num, d.leader, d.phone, d.email, d.status, d.del_flag, d.create_by, d.create_time, d.dept_level,d.bussness_unit, CASE WHEN d.parent_id = '1' THEN NULL WHEN d.parent_id = '100000' THEN d.dept_id ELSE d.parent_id END province, CASE WHEN d.parent_id = '1' THEN NULL WHEN d.parent_id = '100000' THEN NULL ELSE d.dept_id END city,d.app_ver_code, d.MDM_ORG_CODE as mdmOrgCode,d.industry_code as industryCode from sys_dept d left join sys_tenant_info s on d.tenant_id = s.tenant_id where d.del_flag = 0 and d.status = '0' AND d.TENANT_ID is not null
AND d.tenant_id = #{tenantId}
AND d.industry_code = #{industryCode}

select s.tenant_name, d.TENANT_ID as tenantId, d.TENANT_TOWER_DEPT_ID as tenantTowerDeptId, d.id, d.dept_id, d.parent_id, d.parent_name, d.ancestors, d.dept_name, d.order_num, d.leader, d.phone, d.email, d.status, d.del_flag, d.create_by, d.create_time, d.dept_level,d.bussness_unit, CASE WHEN d.parent_id = '1' THEN NULL WHEN d.parent_id = '100000' THEN d.dept_id ELSE d.parent_id END province, CASE WHEN d.parent_id = '1' THEN NULL WHEN d.parent_id = '100000' THEN NULL ELSE d.dept_id END city,d.app_ver_code, d.MDM_ORG_CODE as mdmOrgCode,d.industry_code as industryCode from sys_dept d left join sys_tenant_info s on d.tenant_id = s.tenant_id where d.del_flag = 0 and d.status = '0' AND d.TENANT_ID is not null and (d.parent_id = '000000' or d.parent_id = '无')
AND d.tenant_id = #{tenantId}
AND d.industry_code in
#{item}
group by d.tenant_id, d.industry_code

